(()=>{const t=location.pathname,o=t==="/connect",n=t==="/connect/google";if(!(!o&&!n))try{chrome.runtime.sendMessage({type:"GET_EXTENSION_KEY"},e=>{if(!(chrome.runtime.lastError||!e?.key)){if(n){document.documentElement.setAttribute("data-na-device-key",e.key),window.postMessage({__na:"device-key",key:e.key},location.origin);return}fetch("/api/connect",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({extension_key:e.key})}).then(i=>{i.ok&&(location.href="/")})}})}catch{}})();
